from flask import Flask, request, make_response

app = Flask(__name__)

@app.route('/showName')
def name():
    '''
    Get "name" from the request, validate it,
    make a response with it, and return the response object
    '''
    # Validate and sanitize the input
    user_name = request.args.get('name', '')
    if not user_name:
        response = make_response("Name parameter is missing", 400)
    else:
        # Basic validation: allow alphabets, spaces, and basic punctuation only
        import re
        if re.match("^[a-zA-Z\s\-\']+$", user_name):
            response = make_response(f"Hello, {user_name}", 200)
        else:
            response = make_response("Invalid name parameter", 400)

    return response

if __name__ == "__main__":
    app.run(debug=True)
